/*
frontier_special_trainer_spreads.h
	set up battle frontier species for special trainers, including EVs, IVs, nature, ability, ball type, etc!
	
structs to edit:
	gSpecialTowerSpread_{Person}
	gLegendaryTowerSpread (shared by every special trainer, at the end of this file)

Each must always have at least 4 species (to support 4v4 doubles), but can have as many variations per species as desired. These are chosen from at random while building the team.
*/

